// ApproveWarrantyWaiver applies one pending waiver and records the fee adjustment atomically.
func ApproveWarrantyWaiver(ctx context.Context, caps capabilities.ApproveWarrantyWaiverCapabilities, input capabilities.ApproveWarrantyWaiverInput) (capabilities.ApproveWarrantyWaiverOutput, error) {
	principal := caps.Execution.Principal()
	if !principal.Known || principal.UserID == "" {
		return capabilities.ApproveWarrantyWaiverOutput{}, reject("authorization.forbidden")
	}

	targetID := caps.Execution.TargetID()
	waiver, err := caps.WarrantyWaiver.GetForUpdate(ctx, targetID)
	if err != nil {
		return capabilities.ApproveWarrantyWaiverOutput{}, err
	}
	if waiver.Status != schema.WarrantyWaiverStatus("pending") {
		return capabilities.ApproveWarrantyWaiverOutput{}, reject("state.conflict")
	}

	updated, err := caps.WarrantyWaiver.ConditionalUpdate(ctx, data.NewWarrantyWaiverUpdate(targetID).
		WithExpectedUpdatedAt(waiver.UpdatedAt).
		RequireStatusEqual(schema.WarrantyWaiverStatus("pending"), "state.conflict").
		SetStatus(schema.WarrantyWaiverStatus("applied")).
		SetDecidedAt(input.DecidedAt).
		SetDecidedByUserID(principal.UserID).
		ClearRejectionReason())
	if err != nil {
		return capabilities.ApproveWarrantyWaiverOutput{}, err
	}

	waiverReference := schema.NewFeeLedgerWarrantyWaiverIDReference(updated.ID)
	if _, err = caps.FeeLedger.Create(ctx, schema.CreateFeeLedger{
		Amount:           schema.FeeLedgerAmount(updated.RequestedAmount),
		CalculationTrace: "applied_waiver=requested_amount",
		InputSnapshot:    `{"decision":"manager_approved"}`,
		Kind:             schema.FeeLedgerKind("waiver"),
		LineageKey:       "warranty_waiver:" + string(updated.ID),
		OccurredAt:       input.DecidedAt,
		PolicySnapshot:   updated.PolicySnapshot,
		ServiceRequestID: schema.NewFeeLedgerServiceRequestIDReference(updated.ServiceRequestID.ID()),
		WarrantyWaiverID: &waiverReference,
	}); err != nil {
		return capabilities.ApproveWarrantyWaiverOutput{}, err
	}

	if updated.RequesterUserID == nil || *updated.RequesterUserID == "" {
		return capabilities.ApproveWarrantyWaiverOutput{}, reject("waiver.requester_missing")
	}
	requestID, result := string(updated.ServiceRequestID.ID()), "approved"
	if _, err = caps.Notifications.Dispatch(ctx, capabilities.ApproveWarrantyWaiverNotificationIntent{
		EventType: "warranty_waiver.resolved", SourceEventID: "warranty_waiver.resolved:" + string(updated.ID),
		RecipientUserIDs: []string{*updated.RequesterUserID}, Surface: "business_workspace",
		SubjectObjectKey: "warranty_waiver", SubjectRecordID: string(updated.ID), SubjectVersion: updated.UpdatedAt,
		DedupeKey: "warranty_waiver.resolved:" + string(updated.ID), GroupKey: "service_request:" + requestID,
		Alert: true, OccurredAt: input.DecidedAt,
		Variables: []capabilities.ApproveWarrantyWaiverNotificationVariable{{Key: "request_id", StringValue: &requestID}, {Key: "result", StringValue: &result}},
	}); err != nil {
		return capabilities.ApproveWarrantyWaiverOutput{}, err
	}

	return capabilities.ApproveWarrantyWaiverOutput{Status: schema.WarrantyWaiverApproveWarrantyWaiverStatusApplied, WarrantyWaiverID: updated.ID}, nil
}
