    summary, redacted = sanitize_diagnostic_message(summary)
    return {
        "summary": summary,
        "original_bytes": len(stderr),
        "retained_bytes": len(retained),
        "truncated": len(stderr) > len(retained),
        "redacted": redacted,
    }


