DATABASE_COHORT_CONTRACT = "domainry-managed-runtime-database-cohort-v1"

DENOMINATOR_RELATIVE = ".domainry/builder/acceptance/denominator.json"
RUNTIME_STATE_RELATIVE = ".domainry/builder/runtime/runtime-process.json"
SECRETS_RELATIVE = ".domainry/builder/runtime/acceptance-secrets.json"
DEFAULT_RESULTS_RELATIVE = "backend/tests/evidence/backend-acceptance-results.json"
DEFAULT_EVIDENCE_ROOT = ".domainry/development/acceptance-evidence"

